    async deleteChat({ state, getters }, chat) {
      if (!chat?.id) return

      const descendants = getters.chatDescendants(chat.id) || []
      const chatIds = [chat.id, ...(descendants || []).map(c => c.id)]

      if (!chat.temp) {
        const project = getChatProject(chat)
        await project.$api.chats.delete(chat)
      }

      chatIds.forEach(id => {
